  'decision-rule-para2' => 'आपके भेजने से पहले बायोडाटा समाप्त हो जाता है, इसलिए यह पीडीएफ के रूप में जाता है। दोनों पक्षों द्वारा समीक्षा किया जा रहा अनुबंध मसौदा अंतिम संस्करण पर सहमति होने तक DOCX के रूप में रहता है, फिर हस्ताक्षर करने के लिए पीडीएफ के रूप में सहेजा जाता है। जब आप एक चालान बनाते हैं तो वह समाप्त हो जाता है, इसलिए इसे पीडीएफ के रूप में भेजा जाता है। एक टीम द्वारा संपादित की जा रही बजट स्प्रेडशीट अंतिम संख्या लॉक होने तक अपने मूल प्रारूप के रूप में रहती है।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-para1' => 'एक बार जब आप समझ जाते हैं कि प्रत्येक प्रारूप किस लिए डिज़ाइन किया गया है तो पीडीएफ बनाम DOCX का निर्णय सरल हो जाता है। पीडीएफ साझा करने, मुद्रण और संग्रह करने के लिए दृश्य प्रस्तुति को सुरक्षित रखता है। DOCX संपादन, सहयोग और टेम्पलेट-आधारित दस्तावेज़ उत्पादन को सक्षम बनाता है। अधिकांश पेशेवर दस्तावेज़ वर्कफ़्लो निर्माण के दौरान DOCX और अंतिम वितरण के लिए PDF दोनों का उपयोग करते हैं।',
  'conclusion-para2' => 'प्रारूपों के बीच कनवर्ट करने के लिए, पीडीएफटूल्स पर पीडीएफ से वर्ड टूल और वर्ड से पीडीएफ टूल देखें, जो दोनों मुफ़्त हैं और पंजीकरण की आवश्यकता नहीं है।',
  'faqs-heading' => 'अक्सर पूछे जाने वाले प्रश्नों',
  'faq1-question' => 'क्या DOCX को PDF में बदलने से गुणवत्ता कम हो जाती है?',
  'faq1-answer' => 'नहीं, जब सही ढंग से किया जाए. Microsoft Word के मूल निर्यात फ़ंक्शन या PDFTools जैसे गुणवत्ता कनवर्टर का उपयोग करके एक PDF तैयार किया जाता है जो Word दस्तावेज़ के समान दिखता है। रूपांतरण रूपांतरण के समय सभी फ़ॉन्ट, चित्र और फ़ॉर्मेटिंग को कैप्चर करता है। वर्चुअल प्रिंटर के माध्यम से प्रिंट टू पीडीएफ विधि का उपयोग करने से बचें, क्योंकि इससे छवि रिज़ॉल्यूशन कम हो सकता है।',
  'faq2-question' => 'क्या पीडीएफ बनने के बाद उसे संपादित किया जा सकता है?',
  'faq2-answer' => 'हाँ, सीमाओं के साथ. एडोब एक्रोबैट प्रो पीडीएफ के भीतर पाठ संपादन की अनुमति देता है, लेकिन इसे पर्याप्त पुनर्लेखन के लिए डिज़ाइन नहीं किया गया है। सार्थक संपादनों के लिए, पीडीएफ को वापस DOCX में परिवर्तित करना आमतौर पर अधिक व्यावहारिक होता है। छोटे सुधारों के लिए, एक समर्पित पीडीएफ संपादक अच्छा काम करता है।',
  'faq3-question' => 'दस्तावेज़ों को ऑनलाइन प्रकाशित करने के लिए कौन सा प्रारूप बेहतर है?',
  'faq3-answer' => 'किसी वेब पेज पर पढ़ी जाने वाली सामग्री के लिए, HTML दोनों से बेहतर है। वेबसाइटों पर प्रकाशित डाउनलोड करने योग्य दस्तावेज़ों के लिए, पीडीएफ को DOCX की तुलना में अधिक पसंद किया जाता है क्योंकि यह बिना किसी सॉफ़्टवेयर के ब्राउज़र में सही ढंग से प्रदर्शित होता है, और इसे खोज इंजन द्वारा अनुक्रमित किया जाता है।',
  'faq4-question' => 'क्या DOCX फ़ाइलें PDF से छोटी हैं?',
  'faq4-answer' => 'यह सामग्री पर निर्भर करता है. टेक्स्ट-भारी दस्तावेज़ों के लिए, DOCX आमतौर पर छोटा होता है। छवि-भारी दस्तावेज़ों के लिए, एक संपीड़ित पीडीएफ अक्सर समकक्ष DOCX से छोटा होता है। पीडीएफ बनाने के बाद पीडीएफटूल्स पर कंप्रेशन टूल का उपयोग करना अक्सर साझा करने के लिए फ़ाइल आकार को कम करने का सबसे प्रभावी तरीका है।',
  'a' => '<a href="' . localized_route('pdf-to-word') . '">पीडीएफ से वर्ड कनवर्टर</a>',
  'a2' => '. रूपांतरण पाठ, तालिकाओं और अधिकांश स्वरूपण को संरक्षित करता है, हालांकि जटिल लेआउट को रूपांतरण के बाद मामूली समायोजन की आवश्यकता हो सकती है।',
  'b' => '<a href="' . localized_route('word-to-pdf') . '">वर्ड टू पीडीएफ टूल</a>',
  'b2' => 'बिना किसी सॉफ़्टवेयर आवश्यकता के रूपांतरण को सेकंडों में संभाल लेता है।',
);
